Here is the root cause:
The bug is caused by the immediate destruction of the Queue Pair (QP) and freeing of the link group after transitioning to the Error state without waiting for all received Work Requests (WRs) to be completed. This leads to a situation where the system may attempt to access memory that has already been freed, resulting in a potential crash due to accessing invalid memory addresses.

Here is the patch:

 static inline void smc_wr_rx_process_cqes(struct ib_wc wc[], int num)
 {
 	struct smc_link *link;
 	int i;

 	for (i = 0; i < num; i++) {
 		link = wc[i].qp->qp_context;
+		link->wr_rx_id_compl = wc[i].wr_id;
 		if (wc[i].status == IB_WC_SUCCESS) {
 			link->wr_rx_tstamp = jiffies;
 			smc_wr_rx_demultiplex(&wc[i]);
 			smc_wr_rx_post(link); /* refill WR RX */
 		} else {
 			/* handle status errors */
 			switch (wc[i].status) {
 			case IB_WC_RETRY_EXC_ERR:
 			case IB_WC_RNR_RETRY_EXC_ERR:
 			case IB_WC_WR_FLUSH_ERR:
 				smcr_link_down_cond_sched(link);
+				if (link->wr_rx_id_compl == link->wr_rx_id)
+					wake_up(&link->wr_rx_empty_wait);
 				break;
 			default:
 				smc_wr_rx_post(link); /* refill WR RX */
 				break;
 			}
 		}
 	}
 }


 void smc_wr_free_link(struct smc_link *lnk)
 {
 	struct ib_device *ibdev;

 	if (!lnk->smcibdev)
 		return;
 	ibdev = lnk->smcibdev->ibdev;

+	smc_wr_drain_cq(lnk);
 	smc_wr_wakeup_reg_wait(lnk);
 	smc_wr_wakeup_tx_wait(lnk);

 	smc_wr_tx_wait_no_pending_sends(lnk);
 	wait_event(lnk->wr_reg_wait, (!atomic_read(&lnk->wr_reg_refcnt)));
 	wait_event(lnk->wr_tx_wait, (!atomic_read(&lnk->wr_tx_refcnt)));

 	if (lnk->wr_rx_dma_addr) {
 		ib_dma_unmap_single(ibdev, lnk->wr_rx_dma_addr,
 				    SMC_WR_BUF_SIZE * lnk->wr_rx_cnt,
 				    DMA_FROM_DEVICE);
 		lnk->wr_rx_dma_addr = 0;
 	}
 	if (lnk->wr_rx_v2_dma_addr) {
 		ib_dma_unmap_single(ibdev, lnk->wr_rx_v2_dma_addr,
 				    SMC_WR_BUF_V2_SIZE,
 				    DMA_FROM_DEVICE);
 		lnk->wr_rx_v2_dma_addr = 0;
 	}
 	if (lnk->wr_tx_dma_addr) {
 		ib_dma_unmap_single(ibdev, lnk->wr_tx_dma_addr,
 				    SMC_WR_BUF_SIZE * lnk->wr_tx_cnt,
 				    DMA_TO_DEVICE);
 		lnk->wr_tx_dma_addr = 0;
 	}
 	if (lnk->wr_tx_v2_dma_addr) {
 		ib_dma_unmap_single(ibdev, lnk->wr_tx_v2_dma_addr,
 				    SMC_WR_BUF_V2_SIZE,
 				    DMA_TO_DEVICE);
 		lnk->wr_tx_v2_dma_addr = 0;
 	}
 }


 int smc_wr_create_link(struct smc_link *lnk)
 {
 	struct ib_device *ibdev = lnk->smcibdev->ibdev;
 	int rc = 0;

 	smc_wr_tx_set_wr_id(&lnk->wr_tx_id, 0);
 	lnk->wr_rx_id = 0;
 	lnk->wr_rx_dma_addr = ib_dma_map_single(
 		ibdev, lnk->wr_rx_bufs,	SMC_WR_BUF_SIZE * lnk->wr_rx_cnt,
 		DMA_FROM_DEVICE);
 	if (ib_dma_mapping_error(ibdev, lnk->wr_rx_dma_addr)) {
 		lnk->wr_rx_dma_addr = 0;
 		rc = -EIO;
 		goto out;
 	}
 	if (lnk->lgr->smc_version == SMC_V2) {
 		lnk->wr_rx_v2_dma_addr = ib_dma_map_single(ibdev,
 			lnk->lgr->wr_rx_buf_v2, SMC_WR_BUF_V2_SIZE,
 			DMA_FROM_DEVICE);
 		if (ib_dma_mapping_error(ibdev, lnk->wr_rx_v2_dma_addr)) {
 			lnk->wr_rx_v2_dma_addr = 0;
 			rc = -EIO;
 			goto dma_unmap;
 		}
 		lnk->wr_tx_v2_dma_addr = ib_dma_map_single(ibdev,
 			lnk->lgr->wr_tx_buf_v2, SMC_WR_BUF_V2_SIZE,
 			DMA_TO_DEVICE);
 		if (ib_dma_mapping_error(ibdev, lnk->wr_tx_v2_dma_addr)) {
 			lnk->wr_tx_v2_dma_addr = 0;
 			rc = -EIO;
 			goto dma_unmap;
 		}
 	}
 	lnk->wr_tx_dma_addr = ib_dma_map_single(
 		ibdev, lnk->wr_tx_bufs,	SMC_WR_BUF_SIZE * lnk->wr_tx_cnt,
 		DMA_TO_DEVICE);
 	if (ib_dma_mapping_error(ibdev, lnk->wr_tx_dma_addr)) {
 		rc = -EIO;
 		goto dma_unmap;
 	}
 	smc_wr_init_sge(lnk);
 	bitmap_zero(lnk->wr_tx_mask, SMC_WR_BUF_CNT);
 	init_waitqueue_head(&lnk->wr_tx_wait);
 	atomic_set(&lnk->wr_tx_refcnt, 0);
 	init_waitqueue_head(&lnk->wr_reg_wait);
 	atomic_set(&lnk->wr_reg_refcnt, 0);
+	init_waitqueue_head(&lnk->wr_rx_empty_wait);
 	return rc;

 dma_unmap:
 	if (lnk->wr_rx_v2_dma_addr) {
 		ib_dma_unmap_single(ibdev, lnk->wr_rx_v2_dma_addr,
 				    SMC_WR_BUF_V2_SIZE,
 				    DMA_FROM_DEVICE);
 		lnk->wr_rx_v2_dma_addr = 0;
 	}
 	if (lnk->wr_tx_v2_dma_addr) {
 		ib_dma_unmap_single(ibdev, lnk->wr_tx_v2_dma_addr,
 				    SMC_WR_BUF_V2_SIZE,
 				    DMA_TO_DEVICE);
 		lnk->wr_tx_v2_dma_addr = 0;
 	}
 	ib_dma_unmap_single(ibdev, lnk->wr_rx_dma_addr,
 			    SMC_WR_BUF_SIZE * lnk->wr_rx_cnt,
 			    DMA_FROM_DEVICE);
 	lnk->wr_rx_dma_addr = 0;
 out:
 	return rc;
 }


